import{_ as a,C as i,o as t,c as r,ag as c,E as l}from"./chunks/framework.cyF4XceO.js";const y=JSON.parse('{"title":"概念","description":"Takoform の portability boundary、Form identity、lifecycle。","frontmatter":{"title":"概念","description":"Takoform の portability boundary、Form identity、lifecycle。"},"headers":[],"relativePath":"ja/docs/concepts.md","filePath":"ja/docs/concepts.md"}'),n={name:"ja/docs/concepts.md"};function s(d,e,p,h,m,f){const o=i("StatusNote");return t(),r("div",null,[e[0]||(e[0]=c('<h1 id="概念" tabindex="-1">概念 <a class="header-anchor" href="#概念" aria-label="Permalink to &quot;概念&quot;">​</a></h1><p>Takoform は workload semantics を Form に、運用上の責任を host に寄せます。 Provider の surface を読むときは、次の 3 つの考え方を先に確認してください。</p><h2 id="portability-には境界がある" tabindex="-1">portability には境界がある <a class="header-anchor" href="#portability-には境界がある" aria-label="Permalink to &quot;portability には境界がある&quot;">​</a></h2><p>Form は一つの service primitive の application-visible shape を所有します。 実行 ABI、整合性、配信保証、更新単位、lifecycle がその範囲です。実装、配置、 容量、資格情報、routing、recovery、catalog、billing、quota、SLA は host が 所有します。</p><p>これは、同じ shape を conforming host の間で移動できるという意味です。複数 service の最小公倍数に薄めるという意味ではありません。意味論が異なるなら、 別の Form です。</p><h2 id="form-は-exact-identity-である" tabindex="-1">Form は exact identity である <a class="header-anchor" href="#form-は-exact-identity-である" aria-label="Permalink to &quot;Form は exact identity である&quot;">​</a></h2><p>現行の 4 つの流れを明示します。</p><ul><li>Host API lane は literal な <code>forms.takoform.com/v1</code>。</li><li>Form は <code>formId</code> と <code>definitionVersion</code> を持つ。</li><li>Core ライブラリは独立した SemVer（現在 <code>v1.1.0</code>）を持つ。</li><li>Provider は独立した Registry SemVer（現在 <code>3.0.0</code>）を持つ。</li></ul><p>family は discovery のための grouping であり、versionless です。package envelope、schema <code>$id</code>、digest、Provider descriptor は artifact evidence であり、 隠れた 5 つ目の流れではありません。</p><h2 id="resource-は-lifecycle-graph-を作る" tabindex="-1">resource は lifecycle graph を作る <a class="header-anchor" href="#resource-は-lifecycle-graph-を作る" aria-label="Permalink to &quot;resource は lifecycle graph を作る&quot;">​</a></h2><p>多くの resource は次の順で進みます。</p><ol><li><strong>identity</strong> — service shape と stable UID に名前を付ける。</li><li><strong>revision</strong> — immutable bytes と revision field を宣言または upload する。</li><li><strong>deployment</strong> — traffic を受ける revision を選ぶ。</li><li><strong>attachment</strong> — domain、endpoint、trigger、consumer などの inward edge を付ける。</li></ol><p>Provider は UID、generation、revision の fence 付きで validate、prepare、apply、 observe、delete を送ります。deployment がない、generation が古い、といった状態は contract の不一致であり、version を読み替える理由にはなりません。</p><h2 id="capability-は-host-が所有する" tabindex="-1">capability は host が所有する <a class="header-anchor" href="#capability-は-host-が所有する" aria-label="Permalink to &quot;capability は host が所有する&quot;">​</a></h2><p>apply 前に Provider は Host Support Profile を読み、exact FormRef が対応して いるかを確認します。revision には typed binding で capability を追加します。 配置や資格情報が Form definition に入り込むことはありません。</p><h2 id="次に読むページ" tabindex="-1">次に読むページ <a class="header-anchor" href="#次に読むページ" aria-label="Permalink to &quot;次に読むページ&quot;">​</a></h2><p><a href="/ja/docs/versions.html">バージョンモデル</a>が現行の互換性入口です。旧<a href="/ja/spec/">仕様資料</a> は履歴 source として保持され、旧 decision や receipt を調べるための banner が 表示されます。</p>',17)),l(o)])}const b=a(n,[["render",s]]);export{y as __pageData,b as default};
